############################################################ # PG Setup Code ############################################################ $low = 0; $high = random(1,9,1); $a = random(5,20,1); if($envir{problemSeed}==1){$high=5;$a=10;}; Context("Fraction"); Context()->variables->are(t=>'Real'); $f = FormulaWithUnits("$a ft/s^2"); $F = Formula("$a t"); $D = FormulaWithUnits(Fraction($F->eval(t=>Real($high)) - $F->eval(t=>Real($low))), 'ft/s');
############################################################ # Body ############################################################
BEGIN_PGML An acceleration function of an object moving along a straight line is given. Find the change of the object's velocity over the given time interval.
[`a(t)=[$f]`] on [`[[$low],[$high]]`]
[_]{$D}{10}
END_PGML
